$root = $PSScriptRoot
Write-Host "Applying V3 fixes (Base64 safe mode) to ensure correct encoding..." -ForegroundColor Cyan

# 1. scripts/main.js
$mainJsB64 = ""

# 2. scripts/chm-browser.js
$chmBrowserJsB64 = ""

function Write-B64Content($path, $b64) {
    # Decode B64 to Byte Array
    $bytes = [System.Convert]::FromBase64String($b64)
    # Write bytes directly to avoid PowerShell string encoding mess
    [System.IO.File]::WriteAllBytes($path, $bytes)
    Write-Host "Restored $path from Base64" -ForegroundColor Green
}

Write-B64Content "$root\scripts\main.js" $mainJsB64
Write-B64Content "$root\scripts\chm-browser.js" $chmBrowserJsB64

Write-Host "V3 Fixes (Base64) Complete."
